17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	import java.util.Locale;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        if (isDuplicateTelephone(owner)) {
108	            throw new DuplicateOwnerException("An owner with telephone "
109	                + owner.getTelephone() + " already exists");
110	        }
111	        if (isDuplicateEmail(owner)) {
112	            throw new DuplicateOwnerException("An owner with email "
113	                + owner.getEmail() + " already exists");
114	        }
115	        this.clinicService.saveOwner(owner);
116	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
117	        headers.setLocation(UriComponentsBuilder.newInstance()
118	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
119	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
120	    }
121	
122	    /**
123	     * Determines whether any other owner already uses the candidate's telephone number.
124	     * The comparison ignores letter case and surrounding or repeated whitespace.
125	     *
126	     * @param candidate the owner about to be created
127	     * @return {@code true} if an owner with the same telephone is already present in the data store
128	     */
129	    private boolean isDuplicateTelephone(Owner candidate) {
130	        String telephone = normalize(candidate.getTelephone());
131	        return this.clinicService.findAllOwners().stream()
132	            .anyMatch(existing -> Objects.equals(normalize(existing.getTelephone()), telephone));
133	    }
134	
135	    /**
136	     * Determines whether any other owner already uses the candidate's email address.
137	     * An absent or blank email is never considered a duplicate. The comparison ignores
138	     * letter case and surrounding or repeated whitespace.
139	     *
140	     * @param candidate the owner about to be created
141	     * @return {@code true} if an owner with the same email is already present in the data store
142	     */
143	    private boolean isDuplicateEmail(Owner candidate) {
144	        String email = normalize(candidate.getEmail());
145	        if (email == null || email.isBlank()) {
146	            return false;
147	        }
148	        return this.clinicService.findAllOwners().stream()
149	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
150	    }
151	
152	    /**
153	     * Canonicalises a value for duplicate detection so that comparisons ignore letter
154	     * case and surrounding or repeated whitespace. Surrounding whitespace is stripped,
155	     * any run of internal whitespace is collapsed to a single space, and the result is
156	     * lower-cased. For example {@code "  john   smith "} and {@code "John Smith"} both
157	     * normalise to {@code "john smith"}.
158	     *
159	     * @param value the raw value, possibly {@code null}
160	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
161	     */
162	    private static String normalize(String value) {
163	        if (value == null) {
164	            return null;
165	        }
166	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
172	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
173	        if (currentOwner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        currentOwner.setAddress(ownerFieldsDto.getAddress());
177	        currentOwner.setCity(ownerFieldsDto.getCity());
178	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
179	        currentOwner.setLastName(ownerFieldsDto.getLastName());
180	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
181	        this.clinicService.saveOwner(currentOwner);
182	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Transactional
187	    @Override
188	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
189	        Owner owner = this.clinicService.findOwnerById(ownerId);
190	        if (owner == null) {
191	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
192	        }
193	        this.clinicService.deleteOwner(owner);
194	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
200	        Owner owner = this.clinicService.findOwnerById(ownerId);
201	        if (owner == null) {
202	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	        }
204	        HttpHeaders headers = new HttpHeaders();
205	        Pet pet = petMapper.toPet(petFieldsDto);
206	        owner.setId(ownerId);
207	        pet.setOwner(owner);
208	        pet.getType().setName(null);
209	        this.clinicService.savePet(pet);
210	        PetDto petDto = petMapper.toPetDto(pet);
211	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
212	            .buildAndExpand(pet.getId()).toUri());
213	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
214	    }
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
219	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
220	        if (currentOwner != null) {
221	            Pet currentPet = this.clinicService.findPetById(petId);
222	            if (currentPet != null) {
223	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
224	                currentPet.setName(petFieldsDto.getName());
225	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
226	                this.clinicService.savePet(currentPet);
227	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
228	            }
229	        }
230	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	    }
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Override
235	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
236	        HttpHeaders headers = new HttpHeaders();
237	        Visit visit = visitMapper.toVisit(visitFieldsDto);
238	        Pet pet = new Pet();
239	        pet.setId(petId);
240	        visit.setPet(pet);
241	        this.clinicService.saveVisit(visit);
242	        VisitDto visitDto = visitMapper.toVisitDto(visit);
243	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
244	            .buildAndExpand(visit.getId()).toUri());
245	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
246	    }
247	
248	
249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Override
251	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
252	        Owner owner = this.clinicService.findOwnerById(ownerId);
253	        if (owner != null) {
254	            Pet pet = owner.getPet(petId);
255	            if (pet != null) {
256	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
257	            }
258	        }
259	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	    }
261	}
